/// <summary>
/// <summary>
/// Class to post the shipment confirmation
/// </summary>
class METOrderShipmentConfirmation_SalesOrder extends METOrderShipmentConfirmation
{
}

Method.Source:
/// <summary>
/// Business logic to post the shipment
/// </summary>
/// <returns>Return tag</returns>
public boolean post()
{
    boolean         isPosted;
    boolean         postedPackingSlip = true;
    AccountOrder    accountOrder;

    #OCCRetryCount
    try
    {
        procMetrics = METProcMetricsScope::current();

        if (procMetrics)
        {
            procMetrics.ttsBeginTrace();
        }
        else
        {
            ttsbegin;
        }

        accountOrder = metSalesOrderShipmentLoadHeader.PostMultiDocument == NoYes::No ? AccountOrder::Account : AccountOrder::None;

        using (var context = new METInvoicePostingContext())
        {
            isPosted = this.postPackingSlipReport(metSalesOrderShipmentLoadHeader, accountOrder, orderNum);

            if (!isPosted)
            {
                postedPackingSlip = false;
            }
            else
            {                   
                isPosted = this.postSalesInvoice(metSalesOrderShipmentLoadHeader, orderNum);
            }
        }

        if (procMetrics)
        {
            procMetrics.ttsCommitTrace();
            procMetrics.incProcessedCountWithDocument(metSalesOrderShipmentLoadHeader.ShipmentId);
        }
        else
        {
            ttscommit;
        }
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw;
        }
    }
    //CBNF019_Observability_SalesOrderShipping
    catch
    {
        isPosted = false;
        str failureStep = postedPackingSlip ? "@SYS522" : "@SYS114660";

        METSalesOrderShipmentLoadLines metSalesOrderShipmentLoadLinesTel;
        str errorMessage = this.extractErrorMessagesFromInfolog();

        select firstonly metSalesOrderShipmentLoadLinesTel
            where metSalesOrderShipmentLoadLinesTel.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId;

        if (metSalesOrderShipmentLoadLinesTel.OrderNum != '')
        {
            METTelemetrySOShipmentErrorEvent::runTelemetryEvent(metSalesOrderShipmentLoadLinesTel.OrderNum, errorMessage);
        }

        setPrefix(failureStep);
        error("@MET:ShipConfirmFail");
        Error(errorMessage);
    }

    return isPosted;
}

/// <summary>
/// Method to post the invoice report
/// </summary>
/// <param name = "_shipmentLoadHeader">Shipment load leader</param>
/// <param name = "_accountOrder">Account order</param>
/// <returns>Boolean result</returns>
private boolean postPackingSlipReport(METSalesOrderShipmentLoadHeader  _shipmentLoadHeader, AccountOrder _accountOrder, METOrderReference _orderNum)
{
    boolean                         isPosted = false;
    SalesFormLetter                 salesFormLetter;

    if (procMetrics)
    {
        procMetrics.startDescriptionTime(2, "@MET:CustomerMDFConsolidation");
    }

    this.createPostCustomerMDFConsolidation(metSalesOrderShipmentLoadHeader);

    if (procMetrics)
    {
        procMetrics.endDescriptionTime(2);
    }

    if (procMetrics)
    {
        procMetrics.startDescriptionTime(3, "@SCM:PostPackingSlip");
    }

    salesFormLetter = this.postPackingSlip(_shipmentLoadHeader, _accountOrder, _orderNum);

    if (procMetrics)
    {
        procMetrics.incDescriptionCount(3, 1);
        procMetrics.endDescriptionTime(3);
    }

    if (salesFormLetter.parmJournalRecord().TableId == tableNum(CustPackingSlipJour))
    {
        CustPackingSlipJour     jourTable;
        jourTable = salesFormLetter.parmJournalRecord();           

        if (jourTable)
        {
            if (!_shipmentLoadHeader.PostMultiDocument)
            {
                jourTable.METUpdateLoadShipmentId(_shipmentLoadHeader);
            }
            else
            {
                CustPackingSlipJour::METUpdateLoadShipmentLines(_shipmentLoadHeader);
            }

            Info(strFmt("@MET:DeliveryNotePosted", _shipmentLoadHeader.ShipmentId));

            isPosted = true;
        }
    }      


    return isPosted;
}

/// <summary>
/// Posts a sales invoice for the specified shipment load header.
/// </summary>
/// <param name="_shipmentLoadHeader">The ID of the shipment load header.</param>
/// <param name="_orderNum">The order number reference.</param> 
/// <returns>True if the invoice is successfully posted; otherwise, returns false.</returns>
private boolean postSalesInvoice(METSalesOrderShipmentLoadHeader _shipmentLoadHeader, METOrderReference _orderNum)
{
    METSalesOrderShipmentLoadLines      shipmentLoadLines;
    SalesFormLetter_Invoice             salesFormLetterInvoice;
    boolean                             isPosted = false;

    if (procMetrics)
    {
        procMetrics.startDescriptionTime(4, "@SYS522");
    }

    if (_shipmentLoadHeader.PostMultiDocument)
    {
        while select shipmentLoadLines
                group by orderNum
                    where shipmentLoadLines.ShipmentId == _shipmentLoadHeader.ShipmentId
        {
            salesFormLetterInvoice = this.postInvoice(shipmentLoadLines.OrderNum);                
        }
    }
    else
    {
        salesFormLetterInvoice = this.postInvoiceForShipment(_shipmentLoadHeader.ShipmentId, _orderNum);

    }

    if (procMetrics)
    {
        procMetrics.incDescriptionCount(4, 1);
        procMetrics.endDescriptionTime(4);
    }

    METSalesOrderShipmentLoadLines          metSalesOrderShipmentLoadLines;
    SalesLine                               salesLine;
    CustInvoiceTrans                        invoiceTrans;
    CustInvoiceJour                         invoiceJour;

    invoiceJour.skipDataMethods(true);

    if (procMetrics)
    {
        procMetrics.startDescriptionTime(6, "@MET:UpdateInvJourShipDetails");
    }

    update_recordset invoiceJour
            setting METLoadId = _shipmentLoadHeader.LoadId,
                METShipmentId = _shipmentLoadHeader.ShipmentId
                where invoiceJour.METLoadId == ""
                    && invoiceJour.METShipmentId == ""
            exists join invoiceTrans
                where  invoiceTrans.InvoiceId == invoiceJour.InvoiceId
                    && invoiceTrans.InvoiceDate == invoiceJour.InvoiceDate
                    && invoiceTrans.NumberSequenceGroup == invoiceJour.numberSequenceGroup
                    && invoiceTrans.SalesId == invoiceJour.SalesId
            exists join salesLine
                where salesLine.InventTransId == invoiceTrans.InventTransId
            exists join metSalesOrderShipmentLoadLines
                where metSalesOrderShipmentLoadLines.OrderNum == salesLine.SalesId  &&
                    metSalesOrderShipmentLoadLines.LineNum == salesLine.LineNum     &&
                    metSalesOrderShipmentLoadLines.ShipmentId == _shipmentLoadHeader.ShipmentId;

    if (procMetrics)
    {
        procMetrics.incDescriptionCount(6, invoiceJour.RowCount());
        procMetrics.endDescriptionTime(6);
    }

    if (invoiceJour.RowCount() == 0)
    {
        isPosted = false;
        warning(strFmt("@MET:SalesInvoicePostingFailed", _shipmentLoadHeader.ShipmentId));

    }
    else
    {
        isPosted = true;
        info(strFmt("@MET:InvoicePosted", _shipmentLoadHeader.ShipmentId));
    }

    return isPosted;
}

/// <summary>
/// Method to create and post the customer MDF consolidation
/// </summary>
/// <param name = "_shipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
private void createPostCustomerMDFConsolidation(METSalesOrderShipmentLoadHeader _shipmentLoadHeader)
{
    // Find the customer MDF table record
    MetCustomerMdfTable customerMdfTable = MetCustomerMdfTable::find(_shipmentLoadHeader.CustAccount, _shipmentLoadHeader.SiteId, _shipmentLoadHeader.Warehouse);

    // Check if customer MDF consolidation method is Shipment and application method is Last Invoice of Shipment
    if (customerMdfTable.RecId && 
        customerMdfTable.ConsolidationMethodEDT == METConsolidationMethodEDT::Shipment &&
        customerMdfTable.ApplicationMethodEDT == METApplicationMethodEDT::LastInvoiceOfShipment)
    {
        METCustomerMDFConsolidation_Shipment custMDFConsolidationShipment = new METCustomerMDFConsolidation_Shipment();
        custMDFConsolidationShipment.parmCustAccount(_shipmentLoadHeader.CustAccount);
        custMDFConsolidationShipment.parmSiteId(_shipmentLoadHeader.SiteId);
        custMDFConsolidationShipment.parmWarehouse(_shipmentLoadHeader.Warehouse);
        custMDFConsolidationShipment.parmShipmentId(_shipmentLoadHeader.ShipmentId);
        custMDFConsolidationShipment.process();

        METCustomerMDFPosting_SalesInvoice custMDFPostingSalesInvoice = new METCustomerMDFPosting_SalesInvoice();
        custMDFPostingSalesInvoice.parmCustAccount(_shipmentLoadHeader.CustAccount);
        custMDFPostingSalesInvoice.parmShipmentId(_shipmentLoadHeader.ShipmentId);
        custMDFPostingSalesInvoice.process();
    }
}

/// <summary>
/// Method to post the packing slip
/// </summary>
/// <param name = "_shipmentLoadHeader">ShipmentLoad header table reference</param>
/// <param name = "_accountOrder">Account order</param>
/// <returns>SalesFormLetter</returns>
public SalesFormLetter postPackingSlip(METSalesOrderShipmentLoadHeader _shipmentLoadHeader, AccountOrder _accountOrder, METOrderReference _orderNum)
{
    SalesFormLetter                 salesFormLetter;

    salesFormLetter = SalesFormLetter::construct(DocumentStatus::PackingSlip);

    salesFormLetter.chooseLinesQuery(this.calcQuery(_shipmentLoadHeader.ShipmentId, _orderNum));
    salesFormLetter.transDate(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    salesFormLetter.specQty(SalesUpdate::PickingList);
    salesFormLetter.proforma(NoYes::No);
    salesFormLetter.printout(Printout::Current);
    salesFormLetter.printFormLetter(NoYes::No);
    salesFormLetter.usePrintManagement(NoYes::No);
    salesFormLetter.chooseLines(false, true);
    salesFormLetter.sumBy(_accountOrder);
    salesFormLetter.reArrangeNow(!_shipmentLoadHeader.PostMultiDocument);

    salesFormLetter.run();

    return salesFormLetter;
}

/// <summary>
/// Post the sales order invoice
/// </summary>
/// <param name = "_salesId">SalesId reference</param>
/// <returns>SalesFormLetter</returns>
public SalesFormLetter_Invoice postInvoice(SalesId  _salesId)
{
    SalesFormLetter_Invoice     salesFormLetter;
    CustPackingSlipJour         custPackingSlipJour;
    TmpFrmVirtual               tmpFrmVirtual;
    List                        packingSlipList = new List(Types::Record);

    while select custPackingSlipJour where custPackingSlipJour.SalesId == _salesId
    {
        tmpFrmVirtual.clear();

        tmpFrmVirtual.TableNum      = custPackingSlipJour.TableId;
        tmpFrmVirtual.RecordNo      = custPackingSlipJour.RecId;
        tmpFrmVirtual.NoYes         = NoYes::Yes;
        tmpFrmVirtual.Id            = custPackingSlipJour.SalesId;

        tmpFrmVirtual.insert();
        packingSlipList.addEnd(tmpFrmVirtual);
    }

    if (packingSlipList.empty())
    {
        throw Error(strFmt("@MET:SOPackingError", _salesId));
    }

    salesFormLetter = SalesFormLetter::construct(DocumentStatus::Invoice);

    salesFormLetter.salesTable(SalesTable::find(_salesId));
    salesFormLetter.transDate(systemDateGet());
    salesFormLetter.specQty(SalesUpdate::PackingSlip);
    salesFormLetter.proforma(NoYes::No);

    salesFormLetter.selectFromJournal(packingSlipList.pack());

    salesFormLetter.run();

    //NS - CB274
    if (SalesTable::find(_salesId).InterCompanyOrigin == InterCompanyOrigin::Derived)
    {
        if (procMetrics)
        {
            procMetrics.startDescriptionTime(5, "@MET:InterCompSOFinalization");
        }

        METSalesOrderProcessHelper::processPostIntercompanySOFinalization(_salesId, CustInvoiceJour::findFromSalesId(_salesId).InvoiceId);

        if (procMetrics)
        {
            procMetrics.endDescriptionTime(5);
        }
    }
    //NE - CB274

    return salesFormLetter;
}

/// <summary>
/// Post the sales order invoice
/// </summary>
/// <param name = "_shipmentId">SalesId reference</param>
/// <param name = "_orderNum">Order number reference</param>    
/// <returns>SalesFormLetter</returns>
public SalesFormLetter_Invoice postInvoiceForShipment(MetShipmentId  _shipmentId, METOrderReference _orderNum)
{
    METSalesOrderShipmentLoadLines      shipmentLoadLines;
    SalesFormLetter_Invoice salesFormLetter;
    SalesLine       salesLine;
    CustPackingSlipJour custPackingSlipJour;
    TmpFrmVirtual   tmpFrmVirtual;
    List packingSlipList = new List(Types::Record);

    while select custPackingSlipJour
        exists join shipmentLoadLines
            where custPackingSlipJour.SalesId == shipmentLoadLines.OrderNum &&
                  shipmentLoadLines.ShipmentId == _shipmentId &&
                  (_orderNum == '' || shipmentLoadLines.OrderNum == _orderNum)
    {
        tmpFrmVirtual.clear();
        tmpFrmVirtual.TableNum = custPackingSlipJour.TableId;
        tmpFrmVirtual.RecordNo = custPackingSlipJour.RecId;
        tmpfrmvirtual.NoYes = NoYes::Yes;
        tmpFrmVirtual.Id = custPackingSlipJour.SalesId;
        tmpFrmVirtual.insert();
        packingSlipList.addEnd(tmpFrmVirtual);
    }

    if (packingSlipList.empty())
    {
        throw Error(strFmt("@MET:ShipmentNotDelivered", _shipmentId));
    }

    salesFormLetter = SalesFormLetter::construct(DocumentStatus::Invoice);

    salesFormLetter.transDate(systemDateGet());
    salesFormLetter.specQty(SalesUpdate::PackingSlip);
    salesFormLetter.sumBy(AccountOrder::Account);  
    salesFormLetter.proforma(NoYes::No);
    salesFormLetter.selectFromJournal(packingSlipList.pack());
    salesFormLetter.run();

    //NS - CB274

    SalesTable  salesTable;

    while select salesTable
        where salesTable.InterCompanyOrigin == InterCompanyOrigin::Derived
            exists join shipmentLoadLines
                where shipmentLoadLines.OrderNum == salesTable.SalesId  &&
                    shipmentLoadLines.ShipmentId == _shipmentId &&
                    (_orderNum == '' || shipmentLoadLines.OrderNum == _orderNum)
    {
        if (procMetrics)
        {
            procMetrics.startDescriptionTime(5, "@MET:InterCompSOFinalization");
        }

        METSalesOrderProcessHelper::processPostIntercompanySOFinalization(salesTable.SalesId, CustInvoiceJour::findFromSalesId(salesTable.SalesId).InvoiceId);

        if (procMetrics)
        {
            procMetrics.endDescriptionTime(5);
        }
    }
    //NE - CB274

    return SalesFormLetter;
}

/// <summary>
/// Calculate query based on shipment Id
/// </summary>
/// <param name = "_shipmentId">Shipment Id reference</param>
/// <param name = "_orderNum">Order number reference</param>
/// <returns>SysQueryRun</returns>
private SysQueryRun calcQuery(MetShipmentId _shipmentId,  METOrderReference _orderNum)
{        
    Query                   qry = new Query(QueryStr(SalesUpdate));
    QueryBuildDataSource    queryBuildDataSource = qry.dataSourceTable(tableNum(SalesLine));
    QueryBuildDataSource    qbdsShipmentLines;
    SysQueryRun             queryRun;        

    // Bug 383086: [MS] Invoicing_ALM Order_3200 Sales Lines Invoicing throwing errors_SQL DB issues
    // Adding one range/value per salesLine doesn't work for 3200
    // Instead update the query to filter by ShipmentId
    queryBuildDataSource.addRange(fieldnum(SalesLine, SalesStatus)).value(SysQuery::value(SalesStatus::Backorder));

    qbdsShipmentLines = queryBuildDataSource.addDataSource(tableNum(METSalesOrderShipmentLoadLines));
    qbdsShipmentLines.joinMode(JoinMode::ExistsJoin);
    qbdsShipmentLines.addLink(fieldNum(SalesLine, InventTransId), fieldNum(METSalesOrderShipmentLoadLines, InventTransId));
    qbdsShipmentLines.addRange(fieldNum(METSalesOrderShipmentLoadLines, ShipmentId)).value(SysQuery::value(_shipmentId));

    if (_orderNum)
    {
        qbdsShipmentLines.addRange(fieldNum(METSalesOrderShipmentLoadLines, OrderNum)).value(SysQuery::value(_orderNum));
    }

    queryRun = new SysQueryRun(qry);

    int counter = SysQuery::countLoops(queryRun);

    if (procMetrics)
    {
        procMetrics.setLineCount(counter);
    }

    if (!counter)
    {
        throw Error(strFmt("@MET:NoValidShipment", _shipmentId));
    }
    return queryRun;
}

/// <summary>
/// Extract error messages from the Infolog
/// </summary>
/// <returns>Concatenated error messages from Infolog</returns>
private str extractErrorMessagesFromInfolog()
{
    str errorMessage = "";
    SysInfologEnumerator enumerator;
    SysInfologMessageStruct msgStruct;

    enumerator = SysInfologEnumerator::newData(infolog.cut());
    while (enumerator.moveNext())
    {
        msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
        errorMessage += msgStruct.message() + "\n ";
    }

    return errorMessage;
}
